fn bitwise_or(a: Vec<u8>, b: Vec<u8>) -> Vec<u8> {
    // We assume `a` and `b` have the same length.
    assert_eq!(a.len(), b.len(), "Input vectors must have the same length");

    // Zip the two vectors together, apply bitwise OR to each pair,
    // and collect the results into a new vector.
    a.into_iter()
     .zip(b.into_iter())
     .map(|(x, y)| x | y)
     .collect()
}

